template <bool B>
inline bool VerifyClientMsg(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, ClientMsg type) {
  switch (type) {
    case ClientMsg_NONE: {
      return true;
    }
    case ClientMsg_Join: {
      auto ptr = reinterpret_cast<const cyberpunk_rp::protocol::Join *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientMsg_PositionUpdate: {
      auto ptr = reinterpret_cast<const cyberpunk_rp::protocol::PositionUpdate *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientMsg_ClientTimeReport: {
      auto ptr = reinterpret_cast<const cyberpunk_rp::protocol::ClientTimeReport *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientMsg_AdminCommand: {
      auto ptr = reinterpret_cast<const cyberpunk_rp::protocol::AdminCommand *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientMsg_Leave: {
      auto ptr = reinterpret_cast<const cyberpunk_rp::protocol::Leave *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyClientMsgVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyClientMsg(
        verifier,  values->Get(i), types->GetEnum<ClientMsg>(i))) {
      return false;
    }
  }
  return true;
}

